300	/// is intentional rather than a typed `SessionError` so the failure
301	/// surfaces immediately rather than being silently treated as a backend
302	/// error.
303	#[derive(Debug, Default)]
304	pub struct MemorySession {
305	    inner: std::sync::Mutex<Vec<SessionEvent>>,
306	}
307	
308	impl MemorySession {
309	    /// Create an empty [`MemorySession`].
310	    pub fn new() -> Self {
311	        Self::default()
312	    }
313	}
314	
315	#[async_trait]
316	impl Session for MemorySession {
317	    async fn append(&self, events: &[SessionEvent]) -> Result<(), SessionError> {
318	        let mut guard = self.inner.lock().expect("MemorySession mutex poisoned");
319	        guard.extend_from_slice(events);
320	        Ok(())
321	    }
322	
323	    async fn events(&self, since: Option<SequenceId>) -> Result<Vec<SessionEvent>, SessionError> {
324	        let guard = self.inner.lock().expect("MemorySession mutex poisoned");
325	        // `since` is *exclusive* — matches the existing trait doc ("those
326	        // after `since`"). `try_from` ensures 32-bit targets fail loudly
327	        // instead of wrapping past `u32::MAX`; `saturating_add` then guards
328	        // the +1 against the SequenceId(u64::MAX) edge case on 64-bit where
329	        // usize::MAX + 1 would overflow. Both branches are unreachable in
330	        // practice; the saturated result clamps `start` so the slice below
331	        // returns an empty Vec rather than wrapping.
332	        let start = match since {
333	            Some(s) => usize::try_from(s.0)
334	                .expect("SequenceId exceeds platform usize")
335	                .saturating_add(1),
336	            None => 0,
337	        };
338	        Ok(guard.get(start..).unwrap_or(&[]).to_vec())
339	    }
340	
341	    async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError> {
342	        let events = self.events(None).await?;
343	        Ok(project(&events))
344	    }
345	}
346	
347	/// Project an append-only [`SessionEvent`] log into a [`ConversationSnapshot`]
348	/// — the canonical message-list view that providers consume.
349	///
350	/// **Provider-translator caveat:** `Compacted` events render as
351	/// [`Item::System`]. Both shipped provider translators (SMA-316 OpenAI,
352	/// SMA-317 Anthropic) reshape system messages — Anthropic hoists every
353	/// `Item::System` into the top-level `system` field; OpenAI concatenates
354	/// multiple system blocks into one at the top of the conversation. The
355	/// "summary replaces turns 1..N at this position" semantic is therefore
356	/// observation-only in the event log; the model sees the summary text but
357	/// as a top-level system instruction, not a positional cutover.
358	///
359	/// **Repair of old handoff logs.** A session stored by core 0.6.0 or earlier
360	/// (before SMA-810) has the result of each handoff transfer call at the end
361	/// of the run, after the events of the target agent. `project` moves each such
362	/// result to directly after the transfer calls of its handoff response, in
363	/// call order. If a moved result has the synthetic cancel text, `project`
364	/// replaces it with `transferred to {target}` (the first transfer call of the
365	/// response) or `transfer not performed: this response already transferred
366	/// to {target}` (each other transfer call). No other result moves, and the
367	/// number of messages does not change. For such a log, the snapshot order
368	/// therefore no longer follows the event order one-to-one. The stored log
369	/// does not change. A log with no `HandoffOccurred` event, and a log in the
370	/// current layout, project in event order.
371	pub fn project(events: &[SessionEvent]) -> ConversationSnapshot {
372	    let (mut messages, sources) = project_events(events);
373	    let moved = repair_legacy_transfer_results(events, &mut messages, &sources);
374	    if moved > 0 {
375	        tracing::debug!(
376	            target: "paigasus::core::session",
377	            moved,
378	            "repaired legacy handoff transfer results"
379	        );
380	    }
381	    ConversationSnapshot { messages }
382	}
383	
384	/// The index where the run of `ToolCalled` / `AssistantMessage` events
385	/// directly before `handoff_at` starts.
386	///
387	/// The `ToolCalled` events in `start..handoff_at` are the transfer calls of
388	/// the handoff response that the `HandoffOccurred` at `handoff_at` records.
389	pub(crate) fn transfer_run_start(events: &[SessionEvent], handoff_at: usize) -> usize {
390	    handoff_at
391	        - events[..handoff_at]
392	            .iter()
393	            .rev()
394	            .take_while(|e| {
395	                matches!(
396	                    e,
397	                    SessionEvent::ToolCalled { .. } | SessionEvent::AssistantMessage { .. }
398	                )
399	            })
400	            .count()
401	}
402	
403	/// The transfer calls of one handoff response.
404	struct TransferResponse {
405	    /// The incoming agent of the `HandoffOccurred` event.
406	    to: String,
407	    /// The event index of each transfer call, in call order.
408	    calls: Vec<usize>,
409	}
410	
411	/// Move the late result of each handoff transfer call to directly after the
412	/// transfer calls of its response (sessions stored before SMA-810), and give
413	/// a moved synthetic cancel result the transfer text. Returns the number of
414	/// moved results.
415	///
416	/// `sources[m]` is the event index of `messages[m]`. The repair adds and
417	/// removes no message. A result that is already directly after the transfer
418	/// calls (the current layout) does not move, and no other result moves.
419	fn repair_legacy_transfer_results(
420	    events: &[SessionEvent],
421	    messages: &mut Vec<Item>,
422	    sources: &[usize],
423	) -> usize {
424	    // Step 1: the transfer calls of each handoff response.
425	    let mut responses: Vec<TransferResponse> = Vec::new();
426	    let mut is_transfer = vec![false; events.len()];
427	    // `response_at[h]`: the response index of the `HandoffOccurred` at `h`.
428	    let mut response_at: Vec<Option<usize>> = vec![None; events.len()];
429	    // `response_of[c]`: the response index of the transfer call at `c`.
430	    let mut response_of: Vec<Option<usize>> = vec![None; events.len()];
431	    for (at, ev) in events.iter().enumerate() {
432	        if let SessionEvent::HandoffOccurred { to, .. } = ev {
433	            let calls: Vec<usize> = (transfer_run_start(events, at)..at)
434	                .filter(|&i| matches!(events[i], SessionEvent::ToolCalled { .. }))
435	                .collect();
436	            for &c in &calls {
437	                is_transfer[c] = true;
438	                response_of[c] = Some(responses.len());
439	            }
440	            if !calls.is_empty() {
441	                response_at[at] = Some(responses.len());
442	                responses.push(TransferResponse {
443	                    to: to.clone(),
444	                    calls,
445	                });
446	            }
447	        }
448	    }
449	    if responses.is_empty() {
450	        return 0;
451	    }
452	
453	    // Step 2: the result event of each transfer call. A result closes, in
454	    // this order of preference:
455	    // 1. if it is in the run of `ToolReturned` events directly after a
456	    //    `HandoffOccurred`: the earliest open transfer call of that handoff
457	    //    response with its id;
458	    // 2. if it has a transfer text: the earliest open transfer call with its
459	    //    id (a transfer text never closes a non-transfer call while a
460	    //    transfer call with its id is open);
461	    // 3. the most recent open non-transfer call with its id;
462	    // 4. the earliest open transfer call with its id.
463	    let mut result_of: Vec<Option<usize>> = vec![None; events.len()];
464	    let mut open: Vec<(usize, &str)> = Vec::new();
465	    // The response index while the events directly after its handoff are
466	    // `ToolReturned` events.
467	    let mut after_handoff: Option<usize> = None;
468	    for (at, ev) in events.iter().enumerate() {
469	        let handoff_run = after_handoff.take();
470	        match ev {
471	            SessionEvent::HandoffOccurred { .. } => after_handoff = response_at[at],
472	            SessionEvent::ToolCalled { call_id, .. } => open.push((at, call_id)),
473	            SessionEvent::ToolReturned { call_id, .. }
474	            | SessionEvent::ToolDeferred { call_id, .. } => {
475	                let returned = matches!(ev, SessionEvent::ToolReturned { .. });
476	                if returned {
477	                    after_handoff = handoff_run;
478	                }
479	                let of_handoff = handoff_run.filter(|_| returned).and_then(|r| {
480	                    open.iter()
481	                        .position(|&(c, id)| id == call_id && response_of[c] == Some(r))
482	                });
483	                let transfer_text = || {
484	                    matches!(ev, SessionEvent::ToolReturned { content, .. }
485	                        if has_transfer_text(content))
486	                };
487	                let pos = of_handoff
488	                    .or_else(|| {
489	                        transfer_text()
490	                            .then(|| {
491	                                open.iter()
492	                                    .position(|&(c, id)| id == call_id && is_transfer[c])
493	                            })
494	                            .flatten()
495	                    })
496	                    .or_else(|| {
497	                        open.iter()
498	                            .rposition(|&(c, id)| id == call_id && !is_transfer[c])
499	                    })
500	                    .or_else(|| {
501	                        open.iter()
502	                            .position(|&(c, id)| id == call_id && is_transfer[c])
503	                    });
504	                if let Some(p) = pos {
505	                    let (call, _) = open.remove(p);
506	                    if is_transfer[call] && matches!(ev, SessionEvent::ToolReturned { .. }) {
507	                        result_of[call] = Some(at);
508	                    }
509	                }
510	            }
511	            _ => {}
512	        }
513	    }
514	
515	    // Step 3 (done by the caller): the message index of each event.
516	    let mut message_of: Vec<Option<usize>> = vec![None; events.len()];
517	    for (m, &at) in sources.iter().enumerate() {
518	        message_of[at] = Some(m);
519	    }
520	
521	    // Step 4: plan the moves. `inserts` holds (anchor message, moved results);
522	    // `rewrite[m]` holds the new text of a moved cancel result.
523	    let mut moved = vec![false; messages.len()];
524	    let mut rewrite: Vec<Option<String>> = vec![None; messages.len()];
525	    let mut inserts: Vec<(usize, Vec<usize>)> = Vec::new();
526	    for response in &responses {
527	        let Some(last_call) = response.calls.iter().rev().find_map(|&c| message_of[c]) else {
528	            continue;
529	        };
530	        // (message of the result, ordinal of its call in the response)
531	        let results: Vec<(usize, usize)> = response
532	            .calls
533	            .iter()
534	            .enumerate()
535	            .filter(|&(_, &c)| message_of[c].is_some())
536	            .filter_map(|(n, &c)| result_of[c].and_then(|r| message_of[r]).map(|m| (m, n)))
537	            .collect();
538	        let in_place = results
539	            .iter()
540	            .enumerate()
541	            .take_while(|&(k, &(m, _))| m == last_call + 1 + k)
542	            .count();
543	        if in_place == results.len() {
544	            continue;
545	        }
546	        let mut block = Vec::new();
547	        for &(m, n) in &results[in_place..] {
548	            moved[m] = true;
549	            if is_cancel_text(&messages[m]) {
550	                rewrite[m] = Some(if n == 0 {
551	                    format!("transferred to {}", response.to)
552	                } else {
553	                    format!(
554	                        "transfer not performed: this response already transferred to {}",
555	                        response.to
556	                    )
557	                });
558	            }
559	            block.push(m);
560	        }
561	        inserts.push((last_call + in_place, block));
562	    }
563	    if inserts.is_empty() {
564	        return 0;
565	    }
566	    inserts.sort_unstable_by_key(|&(anchor, _)| anchor);
567	
568	    // One rebuild pass.
569	    let count = moved.iter().filter(|&&m| m).count();
570	    let mut slots: Vec<Option<Item>> = std::mem::take(messages).into_iter().map(Some).collect();
571	    for (m, text) in rewrite.into_iter().enumerate() {
572	        if let (Some(text), Some(Item::ToolResult { content, .. })) = (text, slots[m].as_mut()) {
573	            *content = vec![ContentPart::Text { text }];
574	        }
575	    }
576	    let mut out = Vec::with_capacity(slots.len());
577	    let mut next_insert = inserts.into_iter().peekable();
578	    for m in 0..slots.len() {
579	        if !moved[m] {
580	            out.push(slots[m].take().expect("each message is taken once"));
581	        }
582	        while let Some((_, block)) = next_insert.next_if(|(anchor, _)| *anchor == m) {
583	            for r in block {
584	                out.push(slots[r].take().expect("each moved result is taken once"));
585	            }
586	        }
587	    }
588	    *messages = out;
589	    count
590	}
591	
592	/// Whether `content` starts with one of the texts that the runtime gives a
593	/// handoff transfer call: `transferred to `, `transfer not performed: ` or
594	/// `transfer failed: `.
595	fn has_transfer_text(content: &[ContentPart]) -> bool {
596	    matches!(content.first(), Some(ContentPart::Text { text })
597	        if ["transferred to ", "transfer not performed: ", "transfer failed: "]
598	            .iter()
599	            .any(|p| text.starts_with(p)))
600	}
601	
602	/// Whether `item` is a tool result with exactly the synthetic cancel text.
603	fn is_cancel_text(item: &Item) -> bool {
604	    matches!(item, Item::ToolResult { content, .. }
605	        if matches!(content.as_slice(), [ContentPart::Text { text }] if text == CANCELLED_TOOL_CALL_TEXT))
606	}
607	
608	/// Project each event to its message, in event order, with no repair.
609	///
610	/// Returns the messages and, for each message, the index of the event that
611	/// produced it (`sources`). The summary message of a `Compacted` event gets
612	/// the index of that `Compacted` event.
613	fn project_events(events: &[SessionEvent]) -> (Vec<Item>, Vec<usize>) {
614	    let mut messages: Vec<Item> = Vec::new();
615	    let mut sources: Vec<usize> = Vec::new();
616	    // Parallel vec: contributions[i] = number of messages event i produced.
617	    // Needed because Compacted has to undo the message yield of the previous
618	    // N events, and yield varies per variant (HandoffOccurred = 0, others = 1).
619	    let mut contributions: Vec<usize> = Vec::new();
620	
621	    for (at, ev) in events.iter().enumerate() {
622	        match ev {
623	            SessionEvent::UserMessage { content, .. } => {
624	                messages.push(Item::UserMessage {
625	                    content: content.clone(),
626	                });
627	                sources.push(at);
628	                contributions.push(1);
629	            }

