    /// The text of each projected tool result, in order.
    fn shape_of_results(events: &[SessionEvent]) -> Vec<String> {
        shape(events)
            .into_iter()
            .filter(|(kind, _, _)| *kind == "tr")
            .map(|(_, _, t)| t)
            .collect()
    }

