    fn repair_is_a_no_op_on_a_new_layout_log() {
        let run = |n: &str| {
            vec![
                user(n),
                tc(&format!("t{n}"), "transfer_to_budgeting"),
                tc(&format!("u{n}"), "transfer_to_savings"),
