95	/// Stateful `AgentEvent` → AG-UI frame mapper for exactly one run.
96	pub(crate) struct EventMapper {
97	    /// Client-supplied (or generated) thread id, echoed in `RUN_STARTED`/`RUN_FINISHED`.
98	    thread_id: String,
99	    /// Client-supplied (or generated) run id, echoed in `RUN_STARTED`/`RUN_FINISHED`.
100	    run_id: String,
101	    /// Which text-like pair (message or thinking) is currently open, if any.
102	    open_text: OpenText,
103	    /// Id of the currently-open text or thinking message.
104	    current_message: String,
105	    /// Monotonic counter behind `msg-N` ids. Stream-local uniqueness is all AG-UI
106	    /// requires, and deterministic ids let tests assert exact frame sequences.
107	    next_message: u32,
108	    /// Whether the current turn's assistant text has already been streamed via
109	    /// `TokenDelta`. Distinct from `open_text == OpenText::Message`: a `ToolCallDelta`
110	    /// closes the text block (via `close_text`) well before the matching
111	    /// `MessageOutput` arrives, so checking "is a message open right now" would miss
112	    /// that this text was already streamed and re-emit it.
113	    streamed_text: bool,
114	    /// Provider call id → its latest occurrence. A provider id can repeat in one run
115	    /// (see the module doc), so every other per-call field is keyed on the
116	    /// occurrence's AG-UI id instead.
117	    current: HashMap<String, Occurrence>,
118	    /// Every AG-UI id that this run already gave to an occurrence. An alias is never
119	    /// one of these, so it never equals a provider id that the run emitted.
120	    used_ids: HashSet<String>,
121	    /// AG-UI id of the call currently being streamed — has an open `TOOL_CALL_START`
122	    /// and no `TOOL_CALL_END` yet. `None` if no call is currently open.
123	    open_call: Option<String>,
124	    /// Tool name per AG-UI call id, recorded from whichever `ToolCallDelta` first
125	    /// carries one. Only a call's *first* delta populates `name`, but the delta that finally
126	    /// opens that call's span may be a continuation (its buffer resuming, or a
127	    /// revisit), so the name has to be remembered rather than read off the delta at
128	    /// hand — otherwise those spans render as `"unknown"`.
129	    call_names: HashMap<String, String>,
130	    /// Calls whose deltas arrived while a *different* call was open: `(AG-UI id,
131	    /// accumulated args)`. AG-UI permits only one active tool-call span at a
132	    /// time, while core's `ToolCallDelta`s for different ids may interleave freely
133	    /// (`paigasus-helikon-core/src/model.rs:56`) — buffering instead of closing and
134	    /// resuming preserves every args chunk exactly once and never emits an unmatched
135	    /// `TOOL_CALL_END`. A `Vec`, not a map, so flush order is deterministic.
136	    buffered_calls: Vec<(String, String)>,
137	    /// AG-UI call ids whose span has been emitted *and* closed. A `ToolCallItem`
138	    /// arrives long after the deltas it describes, by which time the call's span may already
139	    /// be closed — by its own delta path or by a foreign event that interrupted it.
140	    /// Without this record the item's arm cannot tell "already rendered" from "never
141	    /// streamed, synthesize it", and emits a second complete span for one call.
142	    completed_calls: HashSet<String>,
143	    /// Whether a `STEP_STARTED` is currently unmatched.
144	    step_open: bool,
145	}
