147	impl EventMapper {
148	    /// Create a mapper for one run.
149	    // Constructed by the AG-UI SSE endpoint (SMA-461 Task 6, src/agui/sse.rs) and the
150	    // AG-UI WebSocket endpoint (SMA-461 Task 7, src/agui/ws.rs), one per run in both.
151	    pub(crate) fn new(thread_id: String, run_id: String) -> Self {
152	        Self {
153	            thread_id,
154	            run_id,
155	            open_text: OpenText::None,
156	            current_message: String::new(),
157	            next_message: 0,
158	            streamed_text: false,
159	            current: HashMap::new(),
160	            used_ids: HashSet::new(),
161	            open_call: None,
162	            call_names: HashMap::new(),
163	            buffered_calls: Vec::new(),
164	            completed_calls: HashSet::new(),
165	            step_open: false,
166	        }
167	    }
168	
169	    /// Map one event, emitting any bracketing frames it implies.
170	    // Called per event by both the AG-UI SSE endpoint (SMA-461 Task 6) and the AG-UI
171	    // WebSocket endpoint (SMA-461 Task 7) as each drains an `Agent` run.
172	    pub(crate) fn push(&mut self, ev: &AgentEvent) -> Vec<Value> {
173	        let mut out = Vec::new();
174	        match ev {
175	            AgentEvent::RunStarted { .. } => {
176	                out.push(event::run_started(&self.thread_id, &self.run_id));
177	            }
178	            AgentEvent::TurnStarted { .. } => {
179	                self.close_text(&mut out);
180	                // A tool-call span must not cross the `STEP_FINISHED`/`STEP_STARTED`
181	                // boundary below — it would close inside the *next* step.
182	                self.close_call(&mut out);
183	                self.close_step(&mut out);
184	                self.streamed_text = false;
185	                self.step_open = true;
186	                out.push(event::step_started("turn"));
187	            }
188	            AgentEvent::TokenDelta { text } => {
189	                self.close_call(&mut out);
190	                self.open_text(TextKind::Message, &mut out);
191	                if !text.is_empty() {
192	                    self.streamed_text = true;
193	                    out.push(event::text_message_content(&self.current_message, text));
194	                }
195	            }
196	            AgentEvent::ReasoningDelta { text } => {
197	                self.close_call(&mut out);
198	                self.open_text(TextKind::Thinking, &mut out);
199	                if !text.is_empty() {
200	                    out.push(event::thinking_content(&self.current_message, text));
201	                }
202	            }
203	            AgentEvent::ToolCallDelta {
204	                call_id,
205	                name,
206	                args_delta,
207	            } => {
208	                self.close_text(&mut out);
209	                let call_id = &self.occurrence_for_delta(call_id, name.is_some());
210	                if let Some(name) = name {
211	                    self.call_names
212	                        .entry(call_id.clone())
213	                        .or_insert_with(|| name.clone());
214	                }
215	                if self.open_call.as_deref() == Some(call_id.as_str()) {
216	                    // A continuation of the currently-open call.
217	                    out.push(event::tool_call_args(call_id, args_delta));
218	                } else if self.open_call.is_none() {
219	                    // Nothing else is streaming: open this call now. If chunks for
220	                    // it were buffered while another call held the single active
221	                    // span, replay them first — they were received before this one,
222	                    // and a client concatenating `TOOL_CALL_ARGS` deltas would
223	                    // otherwise rebuild the call's arguments out of order.
224	                    let buffered = self.take_buffered(call_id);
225	                    out.push(event::tool_call_start(
226	                        call_id,
227	                        self.name_of(call_id),
228	                        &self.current_message,
229	                    ));
230	                    if let Some(buffered) = buffered {
231	                        out.push(event::tool_call_args(call_id, &buffered));
232	                    }
233	                    out.push(event::tool_call_args(call_id, args_delta));
234	                    self.open_call = Some(call_id.clone());
235	                } else {
236	                    // A different call is streaming: AG-UI permits only one active
237	                    // span, so buffer this id's content rather than interleaving a
238	                    // second START — it is flushed as a complete span once its own
239	                    // `ToolCallItem` arrives, when a later delta resumes it above,
240	                    // or at the latest when the run ends.
241	                    match self.buffered_calls.iter_mut().find(|(id, _)| id == call_id) {
242	                        Some(entry) => entry.1.push_str(args_delta),
243	                        None => self
244	                            .buffered_calls
245	                            .push((call_id.clone(), args_delta.clone())),
246	                    }
247	                }
248	            }
249	            AgentEvent::ToolCallItem { item } => {
250	                self.close_text(&mut out);
251	                if let Item::ToolCall {
252	                    call_id,
253	                    name,
254	                    args,
255	                } = item
256	                {
257	                    let call_id = &self.occurrence_for_item(call_id);
258	                    if self.open_call.as_deref() == Some(call_id.as_str()) {
259	                        // The call this item describes is the one currently open.
260	                        self.close_call(&mut out);
261	                    } else if let Some(buffered) = self.take_buffered(call_id) {
262	                        // Deltas for this call were buffered while another call was
263	                        // open: flush the whole thing now as one complete,
264	                        // self-contained span. Nothing guarantees `ToolCallItem`s
265	                        // arrive in the order their calls opened, so close whatever
266	                        // is still open first — a complete span emitted inside
267	                        // another one would overlap.
268	                        self.close_call(&mut out);
269	                        self.emit_span(call_id, name, &buffered, &mut out);
270	                    } else if self.completed_calls.contains(call_id) {
271	                        // This call's span is already emitted and closed — by its own
272	                        // deltas above, or by a foreign event (a `TokenDelta`, another
273	                        // call's item) that had to close it to take the single active
274	                        // span. Synthesizing here would emit a second complete span
275	                        // for one call id.
276	                    } else {
277	                        // No deltas were streamed for this call (non-streaming
278	                        // provider): synthesize the whole triple from the item's own
279	                        // args so the client still sees a complete call — again, not
280	                        // nested inside whatever call is currently open.
281	                        self.close_call(&mut out);
282	                        self.emit_span(call_id, name, &args.to_string(), &mut out);
283	                    }
284	                } else {
285	                    out.push(self.custom("helikon.unknown", ev));
286	                }
287	            }
288	            AgentEvent::ToolOutputItem { item } => {
289	                self.close_call(&mut out);
290	                self.close_text(&mut out);
291	                if let Item::ToolResult { call_id, content } = item {
292	                    // The result belongs to the current occurrence of its provider id:
293	                    // in a sequential flow a result comes before the next call that
294	                    // could reuse the id. With no occurrence, the provider id is used,
295	                    // and the run counts it as used, so a later call with that id
296	                    // gets an alias.
297	                    if !self.current.contains_key(call_id) {
298	                        self.used_ids.insert(call_id.clone());
299	                    }
300	                    let call_id = self.agui_id_of(call_id);
301	                    if let Some(buffered) = self.take_buffered(&call_id) {
302	                        // Only possible under `ParallelAgent`: the call is still
303	                        // buffered. Flush it first, with its name, so its result never
304	                        // precedes its own span.
305	                        let name = self.name_of(&call_id).to_owned();
306	                        self.emit_span(&call_id, &name, &buffered, &mut out);
307	                    }
308	                    out.push(event::tool_call_result(&call_id, &text_of(content)));
309	                } else {
310	                    out.push(self.custom("helikon.unknown", ev));
311	                }
312	            }
313	            AgentEvent::MessageOutput { item } => {
314	                // Take the single active span before emitting anything: a synthesized
315	                // text triple nested inside an open `TOOL_CALL_START` would break
316	                // AG-UI's one-active-span rule.
317	                self.close_call(&mut out);
318	                if self.streamed_text {
319	                    // Deltas already streamed this text; only close it.
320	                    self.close_text(&mut out);
321	                } else {
322	                    // No deltas were emitted (non-streaming provider, workflow agent):
323	                    // synthesize the full triple, or the client renders nothing at all.
324	                    // Also closes any dangling thinking block if only `ReasoningDelta`s
325	                    // preceded this `MessageOutput` with no `TokenDelta` at all.
326	                    self.close_text(&mut out);
327	                    let content = match item {
328	                        Item::AssistantMessage { content, .. } => text_of(content),
329	                        _ => String::new(),
330	                    };
331	                    if !content.is_empty() {
332	                        let id = self.new_message_id();
333	                        out.push(event::text_message_start(&id));
334	                        out.push(event::text_message_content(&id, &content));
335	                        out.push(event::text_message_end(&id));
336	                    }
337	                }
338	                self.streamed_text = false;
339	            }
340	            AgentEvent::HandoffItem { .. } => out.push(self.custom("helikon.handoff", ev)),
341	            AgentEvent::AgentUpdated { .. } => out.push(self.custom("helikon.agent_updated", ev)),
342	            AgentEvent::GuardrailTriggered { .. } => out.push(self.custom("helikon.guardrail", ev)),
343	            AgentEvent::ApprovalRequested { call_id, .. } => {
344	                // Keep `call_id` as the provider id (it matches
345	                // `RunDeferred.calls[].call_id`). Add `tool_call_id`, the AG-UI id
346	                // of the current occurrence, so a client can connect the approval
347	                // to the call's span.
348	                let mut frame = self.custom("helikon.approval", ev);
349	                if let Some(value) = frame["value"].as_object_mut() {
350	                    value.insert(
351	                        "tool_call_id".to_owned(),
352	                        Value::String(self.agui_id_of(call_id)),
353	                    );
354	                }
355	                out.push(frame);
356	            }
357	            AgentEvent::PermissionDenied { .. } => {
358	                out.push(self.custom("helikon.permission_denied", ev));
359	            }
360	            AgentEvent::RepairStarted { .. } => out.push(self.custom("helikon.repair", ev)),
361	            AgentEvent::StructuredOutputFailed { .. } => {
362	                out.push(self.custom("helikon.structured_output_failed", ev));
363	            }
364	            AgentEvent::RunCompleted { .. } => {
365	                self.close_all(&mut out);
366	                self.streamed_text = false;
367	                out.push(event::run_finished(&self.thread_id, &self.run_id));
368	            }
369	            AgentEvent::UserMessageInjected { .. } => {
370	                out.push(self.custom("helikon.user_message_injected", ev));
371	            }
372	            // AG-UI has no "stopped" run event. A stop is a controlled end, not a
373	            // failure, so the stream ends with `RUN_FINISHED`; the CUSTOM frame before
374	            // it carries the reason and usage.
375	            AgentEvent::RunStopped { .. } => {
376	                self.close_all(&mut out);
377	                self.streamed_text = false;
378	                out.push(self.custom("helikon.run_stopped", ev));
379	                out.push(event::run_finished(&self.thread_id, &self.run_id));
380	            }
381	            AgentEvent::RunFailed { error } => {
382	                self.close_all(&mut out);
383	                self.streamed_text = false;
384	                out.push(event::run_error("AGENT_ERROR", error));
385	            }
386	            // `AgentEvent` is `#[non_exhaustive]`: a variant added to core later must
387	            // degrade to a lossless CUSTOM event rather than vanish.
388	            other => out.push(self.custom("helikon.unknown", other)),
