396	    // endpoint (SMA-461 Task 7) once their channel from the underlying `Agent` stream
397	    // closes, in case that stream ended without a terminal event (e.g. a misbehaving
398	    // agent, or a connection dropped mid-run).
399	    pub(crate) fn finish(&mut self) -> Vec<Value> {
400	        let mut out = Vec::new();
401	        self.close_all(&mut out);
402	        out
