417	    /// Ensure a text-like pair of kind `kind` is open, closing any different kind
418	    /// that is currently open first. A no-op if `kind` is already open.
419	    fn open_text(&mut self, kind: TextKind, out: &mut Vec<Value>) {
420	        let target = match kind {
421	            TextKind::Message => OpenText::Message,
422	            TextKind::Thinking => OpenText::Thinking,
423	        };
424	        if self.open_text == target {
425	            return;
426	        }
427	        self.close_text(out);
428	        let id = self.new_message_id();
429	        self.current_message = id.clone();
