456	    /// The AG-UI id for a `ToolCallDelta` of provider id `call_id`. A name-carrying
457	    /// delta (`has_name`) starts a new occurrence when the current one already had
458	    /// one, or already had its `ToolCallItem` (an item-only call from a non-streaming
459	    /// provider, then a streamed call that reuses the id); any delta starts one when
460	    /// `call_id` has no occurrence yet.
461	    fn occurrence_for_delta(&mut self, call_id: &str, has_name: bool) -> String {
462	        if let Some(occ) = self.current.get_mut(call_id) {
463	            if !(has_name && (occ.named || occ.item_seen)) {
464	                occ.named |= has_name;
465	                return occ.agui_id.clone();
466	            }
467	        }
468	        let agui_id = self.new_occurrence(call_id);
469	        if let Some(occ) = self.current.get_mut(call_id) {
470	            occ.named = has_name;
471	        }
472	        agui_id
473	    }
