475	    /// The AG-UI id for a `ToolCallItem` of provider id `call_id`. The item starts a
476	    /// new occurrence when the current one already had its item (a non-streamed call
477	    /// that reuses the id), or when `call_id` has no occurrence yet.
478	    fn occurrence_for_item(&mut self, call_id: &str) -> String {
479	        if let Some(occ) = self.current.get_mut(call_id) {
480	            if !occ.item_seen {
481	                occ.item_seen = true;
482	                return occ.agui_id.clone();
483	            }
484	        }
485	        let agui_id = self.new_occurrence(call_id);
486	        if let Some(occ) = self.current.get_mut(call_id) {
487	            occ.item_seen = true;
488	        }
489	        agui_id
490	    }
