492	    /// Start a new occurrence of provider id `call_id` and return its AG-UI id:
493	    /// `call_id` itself when the run has not used it, else `{call_id}~{n}` with the
494	    /// smallest `n` ≥ 2 that the run has not used.
495	    fn new_occurrence(&mut self, call_id: &str) -> String {
496	        let agui_id = if self.used_ids.contains(call_id) {
497	            (2u64..)
498	                .map(|n| format!("{call_id}~{n}"))
499	                .find(|alias| !self.used_ids.contains(alias))
500	                .expect("an unbounded range always yields an unused alias")
501	        } else {
502	            call_id.to_owned()
503	        };
504	        self.used_ids.insert(agui_id.clone());
505	        self.current.insert(
506	            call_id.to_owned(),
507	            Occurrence {
508	                agui_id: agui_id.clone(),
509	                named: false,
510	                item_seen: false,
511	            },
512	        );
513	        agui_id
514	    }
