516	    /// The AG-UI id of the current occurrence of provider id `call_id`, or `call_id`
517	    /// itself when it has none (a result for a call this mapper never saw).
518	    fn agui_id_of(&self, call_id: &str) -> String {
519	        self.current
520	            .get(call_id)
521	            .map_or_else(|| call_id.to_owned(), |occ| occ.agui_id.clone())
522	    }
523	
524	    /// Emit one complete, self-contained span for AG-UI id `call_id` and record it
525	    /// as closed.
526	    fn emit_span(&mut self, call_id: &str, name: &str, args: &str, out: &mut Vec<Value>) {
527	        out.push(event::tool_call_start(call_id, name, &self.current_message));
528	        out.push(event::tool_call_args(call_id, args));
529	        out.push(event::tool_call_end(call_id));
530	        self.completed_calls.insert(call_id.to_owned());
531	    }
532	
533	    /// The tool name recorded for AG-UI id `call_id`, falling back to `"unknown"` only
534	    /// when no delta for it ever carried one.
535	    fn name_of(&self, call_id: &str) -> &str {
536	        self.call_names
537	            .get(call_id)
538	            .map_or("unknown", String::as_str)
539	    }
540	
541	    /// Remove and return the args buffered for AG-UI id `call_id` while a different call
542	    /// held the active span, if any.
543	    fn take_buffered(&mut self, call_id: &str) -> Option<String> {
544	        let pos = self
545	            .buffered_calls
546	            .iter()
547	            .position(|(id, _)| id == call_id)?;
548	        Some(self.buffered_calls.remove(pos).1)
549	    }
