/// Like [`types`] but keeps the full frame, not just its `type` — for tests that
/// need other fields (`toolCallId`, `delta`, …).
fn frames_of(events: &[AgentEvent]) -> Vec<Value> {
    let mut m = mapper();
    let mut out = Vec::new();
    for e in events {
        out.extend(m.push(e));
    }
    out.extend(m.finish());
    out
}

pub(crate) fn tool_call_start(call_id: &str, name: &str, parent: &str) -> Value {
    let mut frame = json!({
        "type": "TOOL_CALL_START",
        "toolCallId": call_id,
        "toolCallName": name,
    });
    if !parent.is_empty() {
        frame["parentMessageId"] = Value::String(parent.to_owned());
    }
    frame
}

toolUseResult.stdout:
    out
}

/// Like [`types`] but keeps the full frame, not just its `type` — for tests that
/// need other fields (`toolCallId`, `delta`, …).
fn frames_of(events: &[AgentEvent]) -> Vec<Value> {
    let mut m = mapper();
    let mut out = Vec::new();
    for e in events {
        out.extend(m.push(e));
    }
    out.extend(m.finish());
    out
}

pub(crate) fn tool_call_start(call_id: &str, name: &str, parent: &str) -> Value {
    let mut frame = json!({
        "type": "TOOL_CALL_START",
        "toolCallId": call_id,
        "toolCallName": name,
    });
    if !parent.is_empty() {
        frame["parentMessageId"] = Value::String(parent.to_owned());
    }
    frame
}
